<script setup lang="ts">
import { computed, ref, onMounted, onBeforeUnmount, watch, nextTick } from 'vue'
import { mountChartMotion, type ChartMotion } from './chart-motion'
const dataset=ref('A'),state=ref('ready'),selected=ref(0),root=ref<HTMLElement|null>(null)
let motion:ChartMotion|undefined
onMounted(()=>{if(root.value)motion=mountChartMotion(root.value,'.skusage-card')})
watch([dataset,state],async()=>{await nextTick();motion?.refresh()})
onBeforeUnmount(()=>motion?.destroy())
const names=['A → X','A → Y','B → X','B → Y']
const values=computed(()=>dataset.value==='A'?[40,20,10,30]:dataset.value==='B'?[10,30,50,10]:dataset.value==='single'?[100,0,0,0]:[0,0,0,0])
const total=computed(()=>values.value.reduce((a,b)=>a+b,0))
const nodes=computed(()=>[{name:'A',x:30,y:40,v:values.value[0]+values.value[1]},{name:'B',x:30,y:190,v:values.value[2]+values.value[3]},{name:'X',x:284,y:40,v:values.value[0]+values.value[2]},{name:'Y',x:284,y:190,v:values.value[1]+values.value[3]}])
const links=computed(()=>values.value.map((v,i)=>{const source=Math.floor(i/2),target=i%2,y0=40+source*150+(target?values.value[i-1]*1.2:0)+v*.6,y1=40+target*150+(source?values.value[target]*1.2:0)+v*.6;return{v,d:`M46,${y0} C165,${y0} 165,${y1} 284,${y1}`}}))
function reset(){dataset.value='A';state.value='ready';selected.value=0}
</script>
<template>
<section ref="root" class="skusage-demo" aria-label="Local Sankey example"><p>Synthetic units transferred from A/B to X/Y. Every link and node uses the same 1.2 SVG units per measured unit, fixed across datasets. Source totals equal destination totals; no loss or intermediate stage is hidden.</p><div class="skusage-controls"><label>Dataset<select v-model="dataset"><option>A</option><option>B</option><option value="single">One flow</option><option value="zero">Zero flow</option></select></label><label>Data state<select v-model="state"><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option></select></label><button type="button" @click="reset">Reset example</button></div><div class="skusage-card"><template v-if="state==='ready'"><p>Total transferred: {{ total }} units. {{ total?'Shares use the full transfer total.':'No transferred units; shares undefined.' }}</p><svg viewBox="0 0 330 340" role="img" aria-label="Sankey from two sources A and B to destinations X and Y. Band thickness is transfer units; exact flows follow in the table."><path v-for="(l,i) in links.filter(l=>l.v>0)" :key="l.d" class="skusage-link" :class="{selected:links[selected].d===l.d}" :d="l.d" :stroke-width="l.v*1.2" fill="none" data-cm="fade"/><g v-for="n in nodes" :key="n.name" class="skusage-node"><text :x="n.x===30?30:300" :y="n.y-10" :text-anchor="n.x===30?'start':'end'">{{ n.name }} · {{ n.v }}</text><rect v-if="n.v>0" :x="n.x" :y="n.y" width="16" :height="n.v*1.2" data-cm="fade"/><line v-else :x1="n.x" :x2="n.x+16" :y1="n.y" :y2="n.y"/></g><text x="30" y="324">Sources</text><text x="300" y="324" text-anchor="end">Destinations</text></svg><div role="group" aria-label="Select transfer" class="skusage-choices"><button v-for="(name,i) in names" :key="name" type="button" :aria-pressed="selected===i" @focus="selected=i" @click="selected=i">{{ name }}</button></div><p role="status">{{ names[selected] }}: {{ values[selected] }} units; {{ total?(100*values[selected]/total).toFixed(1)+'% of total':'share undefined' }}.</p><table class="skusage-data"><caption>Exact transfers, dataset {{ dataset }}</caption><thead><tr><th scope="col">Flow</th><th scope="col">Units</th><th scope="col">Share</th></tr></thead><tbody><tr v-for="(name,i) in names" :key="name"><th scope="row">{{ name }}</th><td>{{ values[i] }}</td><td>{{ total?(100*values[i]/total).toFixed(1)+'%':'N/A' }}</td></tr></tbody></table><p class="skusage-key">Zero-valued links and nodes have no positive thickness/height; a short tick locates a zero node. Curves route flows; curve length and crossings do not encode amount or travel distance. Selection changes opacity, not volume.</p></template><p v-else role="status" class="skusage-state">{{ state==='loading'?'Loading demonstration only; no request is running. Flows are withheld.':'No transfer records in this demonstration state. Choose Ready to recover.' }}</p></div></section>
</template>
<style scoped>
.skusage-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.skusage-controls{display:flex;gap:14px;flex-wrap:wrap;align-items:end}.skusage-controls label{display:flex;gap:8px;align-items:center;font-size:13px}.skusage-demo select{appearance:auto;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);color:var(--vp-c-text-1)}.skusage-demo button{padding:6px 9px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.skusage-demo :is(button,select):focus-visible{outline:2px solid var(--vp-c-brand-1);outline-offset:3px}.skusage-demo svg{display:block;width:100%;height:auto;max-height:420px;margin:16px 0}.skusage-demo svg text{fill:var(--vp-c-text-2);font-size:12px}.skusage-link{stroke:var(--vp-c-brand-1);opacity:.3}.skusage-link.selected{opacity:.85}.skusage-node rect{fill:var(--vp-c-text-1)}.skusage-node line{stroke:var(--vp-c-text-1);stroke-width:2}.skusage-choices{display:flex;gap:6px;flex-wrap:wrap}.skusage-demo button[aria-pressed=true]{background:var(--vp-c-brand-soft);font-weight:700}.skusage-data{display:table!important;width:100%;font-size:12px}.skusage-data caption{text-align:left;padding:8px 0;color:var(--vp-c-text-2)}.skusage-data :is(td,th){padding:6px!important}.skusage-key{font-size:12px;color:var(--vp-c-text-2)}.skusage-state{padding:16px;background:var(--vp-c-bg-soft);border-radius:10px}
</style>
